// Loop through every item received from the upstream AI node
return $input.all().map(item => {
  let record = item.json;

  // 1. Handle potential nested AI response wrappers (e.g., if output is under 'text', 'response', or 'output')
  if (typeof record.text === 'string') {
    try {
      record = JSON.parse(record.text);
    } catch (e) {
      // If it has markdown code block fences (```json ... ```)
      const cleanedText = record.text.replace(/```json/g, '').replace(/```/g, '').trim();
      record = JSON.parse(cleanedText);
    }
  } else if (typeof record.output === 'string') {
    try {
      record = JSON.parse(record.output);
    } catch (e) {
      const cleanedText = record.output.replace(/```json/g, '').replace(/```/g, '').trim();
      record = JSON.parse(cleanedText);
    }
  }

  // 2. Normalize and trim string fields
  const studentId = record.Student_ID ? String(record.Student_ID).trim() : null;
  const name = record.Name ? String(record.Name).trim() : null;
  const course = record.Course ? String(record.Course).trim() : null;
  const city = record.City ? String(record.City).trim() : null;
  const enrolledDate = record.Enrolled_Date ? String(record.Enrolled_Date).trim() : null;

  // 3. Post-validate and sanitize Email
  let email = record.Email ? String(record.Email).trim().toLowerCase() : null;
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  let emailValid = Boolean(record.Email_Valid);

  if (!email || !emailRegex.test(email)) {
    email = null;
    emailValid = false;
  } else {
    emailValid = true;
  }

  // 4. Post-validate and sanitize Phone (strictly 10 digits)
  let rawPhone = record.Phone ? String(record.Phone).replace(/\D/g, '') : '';
  let phone = null;
  let phoneValid = false;

  // Handle standard 10-digit format or 12-digit format with country code '91'
  if (rawPhone.length === 12 && rawPhone.startsWith('91')) {
    rawPhone = rawPhone.slice(2);
  }

  if (rawPhone.length === 10 && !/^0{10}$/.test(rawPhone)) {
    phone = rawPhone;
    phoneValid = true;
  }

  // 5. Enforce strict Boolean for Fee_Paid
  let feePaid = false;
  if (typeof record.Fee_Paid === 'boolean') {
    feePaid = record.Fee_Paid;
  } else if (typeof record.Fee_Paid === 'string') {
    feePaid = record.Fee_Paid.toLowerCase() === 'true';
  }

  // 6. Recalculate or enforce integer for days_since_enrolled
  let daysSinceEnrolled = Number.isInteger(record.days_since_enrolled)
    ? record.days_since_enrolled
    : parseInt(record.days_since_enrolled, 10);

  if (isNaN(daysSinceEnrolled) && enrolledDate) {
    const enrollDateObj = new Date(enrolledDate);
    const targetDate = new Date('2026-10-17');
    const diffTime = targetDate - enrollDateObj;
    daysSinceEnrolled = Math.floor(diffTime / (1000 * 60 * 60 * 24));
  }

  // 7. Overall record status tag (useful for filtering/branching downstream)
  const status = (emailValid && phoneValid) ? 'VALID' : 'REQUIRES_REVIEW';

  return {
    json: {
      Student_ID: studentId,
      Name: name,
      Email: email,
      Email_Valid: emailValid,
      Phone: phone,
      Phone_Valid: phoneValid,
      Course: course,
      Fee_Paid: feePaid,
      City: city,
      Enrolled_Date: enrolledDate,
      days_since_enrolled: daysSinceEnrolled,
      record_status: status
    }
  };
});
